import{_ as o,o as d,c as e,ae as a}from"./chunks/framework.CLL1HkDi.js";const h=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/commands.md","filePath":"guide/commands.md"}'),s={name:"guide/commands.md"};function l(r,t,c,n,m,p){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>All commands start with <code>/plot</code>. Admin-only commands are marked below.</p><h2 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>/plot claim</code></td><td>Claims the plot you are standing on.</td><td><code>plots.claim</code></td></tr><tr><td><code>/plot auto</code></td><td>Automatically claims the nearest free plot.</td><td><code>plots.auto</code></td></tr><tr><td><code>/plot info</code></td><td>Shows information about the current plot.</td><td><code>plots.info</code></td></tr><tr><td><code>/plot tp &lt;name&gt;</code></td><td>Teleports you to one of your plots.</td><td><code>plots.use</code></td></tr><tr><td><code>/plot list</code></td><td>Lists all plots you own.</td><td><code>plots.use</code></td></tr><tr><td><code>/plot rename &lt;name&gt;</code></td><td>Renames your plot.</td><td><code>plots.use</code></td></tr><tr><td><code>/plot trust &lt;player&gt;</code></td><td>Grants a player permission to build on your plot.</td><td><code>plots.use</code></td></tr><tr><td><code>/plot untrust &lt;player&gt;</code></td><td>Removes build permission from a player.</td><td><code>plots.use</code></td></tr><tr><td><code>/plot spawn</code></td><td>Teleports you to the plot world spawn.</td><td><code>plots.spawn</code></td></tr></tbody></table><h2 id="admin-commands" tabindex="-1">Admin Commands <a class="header-anchor" href="#admin-commands" aria-label="Permalink to &quot;Admin Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th>Permission</th></tr></thead><tbody><tr><td><code>/plot delete [x,z]</code></td><td>Deletes the current plot or one at specific coordinates.</td><td><code>plots.admin</code></td></tr><tr><td><code>/plot setspawn</code></td><td>Sets the global spawn point for the plot world.</td><td><code>plots.admin</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Admins with <code>plots.admin</code> bypass all plot protection and can manage any plot on the server.</p></div>',7)])])}const u=o(s,[["render",l]]);export{h as __pageData,u as default};
